// BLAKE2b, BLAKE2s and BLAKE3 (crypto-api 0.8.5 has no BLAKE, so there is no
// original to compare with).
//
// Independent references: the official known-answer tests of BLAKE2 and BLAKE3, RFC 7693,
// `node:crypto` (OpenSSL) for the default BLAKE2 digests and HMAC, and Python's hashlib for
// digest lengths, keys, salts and personalization (test/vectors/blake, generated by
// scripts/gen-blake-vectors.py). Every test that exercises a hasher runs twice: with the wasm
// engine, and with the plain-JavaScript engine that environments without WebAssembly use.
import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createHash, createHmac } from 'node:crypto';
import { readFileSync } from 'node:fs';

import Blake2b, { _internal as b2bInternal } from '../packages/crypto-api/src/hasher/blake2b.mjs';
import Blake2s, { _internal as b2sInternal } from '../packages/crypto-api/src/hasher/blake2s.mjs';
import Blake3, { _internal as b3Internal } from '../packages/crypto-api/src/hasher/blake3.mjs';
import Hasher from '../packages/crypto-api/src/hasher/hasher.mjs';
import Hmac from '../packages/crypto-api/src/mac/hmac.mjs';
import CryptoApi from '../packages/crypto-api/src/crypto-api.mjs';
import { toHex } from '../packages/crypto-api/src/encoder/hex.mjs';
import { fromUtf } from '../packages/crypto-api/src/encoder/utf.mjs';

const vectors = (name) => JSON.parse(readFileSync(new URL(`./vectors/blake/${name}`, import.meta.url), 'utf8'));
const KAT = vectors('blake2-kat.json');
const PARAMS = vectors('blake2-params.json');
const B3 = vectors('blake3.json');

/** The same test inputs as scripts/gen-blake-vectors.py. */
const pattern = (length, tag) => Buffer.from(Array.from({ length }, (_, i) => (i * 31 + tag * 17 + length) & 255));

/** Deterministic pseudo-random bytes. */
function bytes(length, seed) {
  const out = Buffer.alloc(length);
  let x = (Math.imul(seed, 2654435761) + 12345) >>> 0;
  for (let i = 0; i < length; i++) {
    x = (Math.imul(x, 1664525) + 1013904223) >>> 0;
    out[i] = x >>> 24;
  }
  return out;
}

const ALGOS = {
  blake2b: { C: Blake2b, internal: b2bInternal, block: 128, digest: 64, node: 'blake2b512' },
  blake2s: { C: Blake2s, internal: b2sInternal, block: 64, digest: 32, node: 'blake2s256' },
};
const ENGINES = [['wasm', false], ['js', true]];
const INTERNALS = [b2bInternal, b2sInternal, b3Internal];

/** Run `body(engineLabel)` once per engine. */
function perEngine(name, body) {
  for (const [label, disable] of ENGINES) {
    describe(`${name} (${label} engine)`, () => {
      before(() => INTERNALS.forEach((i) => i.reset(disable)));
      after(() => INTERNALS.forEach((i) => i.reset(false)));
      body(label);
    });
  }
}

/** Run `fn` with the plain-JS engine, then restore wasm. */
function withJs(fn) {
  INTERNALS.forEach((i) => i.reset(true));
  try {
    return fn();
  } finally {
    INTERNALS.forEach((i) => i.reset(false));
  }
}

/** Feed `message` to `hasher` in pieces of pseudo-random size 1..maxPiece. */
function feed(hasher, message, seed, maxPiece = 200) {
  let pos = 0;
  let x = seed;
  while (pos < message.length) {
    x = (Math.imul(x, 1664525) + 1013904223) >>> 0;
    const n = 1 + ((x >>> 8) % maxPiece);
    hasher.update(message.subarray(pos, pos + n));
    pos += n;
  }
}

const hashOf = (C, options, message) => {
  const h = new C(options);
  h.update(message);
  return toHex(h.finalize());
};

// ---------------------------------------------------------------------------

describe('which engine runs', () => {
  it('the wasm engine does the work, and the JS engine runs when wasm is switched off', () => {
    for (const [C, internal] of [[Blake2b, b2bInternal], [Blake2s, b2sInternal], [Blake3, b3Internal]]) {
      const run = () => hashOf(C, {}, Buffer.alloc(5000, 7));
      const before = internal.wasmCalls();
      const wasm = run();
      assert.ok(internal.wasmCalls() > before, 'wasm calls');
      assert.ok(internal.runtime(), 'runtime loaded');
      const js = withJs(() => {
        const calls = internal.wasmCalls();
        const out = run();
        assert.equal(internal.runtime(), null);
        assert.equal(internal.wasmCalls(), calls, 'no wasm calls');
        return out;
      });
      assert.equal(js, wasm);
    }
  });
});

perEngine('BLAKE2 known answers', () => {
  it('RFC 7693 appendix A and B: "abc"', () => {
    assert.equal(hashOf(Blake2b, {}, 'abc'),
      'ba80a53f981c4d0d6a2797b69f12f6e94c212f14685ac4b74b12bb6fdbffa2d17d87c5392aab792dc252d5de4533cc9518d38aa8dbf1925ab92386edd4009923');
    assert.equal(hashOf(Blake2s, {}, 'abc'), '508c5e8c327c14e2e1a72ba34eeb452f37458b209ed63a294d999b4c86675982');
  });

  it('the empty message', () => {
    assert.equal(hashOf(Blake2b, {}, ''),
      '786a02f742015903c6c6fd852552d272912f4740e15847618a86e217f71f5419d25e1031afee585313896444934eb04b903a685b1448b755d56f701afe9be2ce');
    assert.equal(hashOf(Blake2s, {}, ''), '69217a3079908094e11121d042354a7c1f55b6482ca1a51e1b250dfd1ed0eef9');
  });

  it(`official known-answer tests (${KAT.length}): keyed and unkeyed, in one update and in pieces`, () => {
    for (const v of KAT) {
      const { C, digest } = ALGOS[v.hash];
      const input = Buffer.from(Array.from({ length: v.inLen }, (_, i) => i));
      const options = v.keyed ? { key: Buffer.from(Array.from({ length: digest }, (_, i) => i)) } : {};
      assert.equal(hashOf(C, options, input), v.hex, `${v.hash} keyed=${v.keyed} len=${v.inLen}`);
      const h = new C(options);
      feed(h, input, v.inLen + 1, 9);
      assert.equal(toHex(h.finalize()), v.hex, `${v.hash} keyed=${v.keyed} len=${v.inLen} (pieces)`);
    }
  });

  it(`digest length, key, salt and personalization against hashlib (${PARAMS.length} vectors)`, () => {
    for (const v of PARAMS) {
      const { C } = ALGOS[v.algo];
      const options = { length: v.length };
      if (v.keyLen) options.key = pattern(v.keyLen, 1);
      if (v.saltLen) options.salt = pattern(v.saltLen, 2);
      if (v.personLen) options.personalization = pattern(v.personLen, 3);
      assert.equal(hashOf(C, options, pattern(v.inLen, 0)), v.hex, JSON.stringify(v));
    }
  });
});

perEngine('BLAKE2 against node:crypto', () => {
  for (const [name, { C, block, node }] of Object.entries(ALGOS)) {
    it(`${name}: every length up to three blocks, random splits`, () => {
      for (let n = 0; n <= 3 * block + 9; n++) {
        const message = bytes(n, n);
        const want = createHash(node).update(message).digest('hex');
        assert.equal(hashOf(C, {}, message), want, `length ${n}`);
        const h = new C();
        feed(h, message, n);
        assert.equal(toHex(h.finalize()), want, `length ${n} (pieces)`);
      }
    });

    it(`${name}: messages larger than the 64 KiB scratch region`, () => {
      for (const n of [65536, 65536 + 1, 3 * 65536 - 1, 200000]) {
        const message = bytes(n, 5);
        const want = createHash(node).update(message).digest('hex');
        assert.equal(hashOf(C, {}, message), want, `length ${n}`);
        const h = new C();
        feed(h, message, 3, 70000);
        assert.equal(toHex(h.finalize()), want, `length ${n} (pieces)`);
      }
    });

    it(`${name}: HMAC with keys shorter than, equal to and longer than a block`, () => {
      for (const keyLen of [0, 1, block / 2, block - 1, block, block + 1, 3 * block]) {
        const key = bytes(keyLen, 11);
        for (const n of [0, 1, block - 1, block, block + 1, 500]) {
          const message = bytes(n, 13);
          const want = createHmac(node, key).update(message).digest('hex');
          const mac = new Hmac(key, new C());
          mac.update(message);
          assert.equal(toHex(mac.finalize()), want, `key ${keyLen}, message ${n}`);
          assert.equal(toHex(mac.finalize()), want, 'second finalize');
        }
      }
    });
  }
});

perEngine('BLAKE3 known answers', () => {
  const key = B3.key;
  const context = B3.context_string;
  const input = (n) => Buffer.from(Array.from({ length: n }, (_, i) => i % 251));

  it(`official test vectors (${B3.cases.length} lengths x 3 modes, 131 output bytes)`, () => {
    for (const c of B3.cases) {
      const message = input(c.input_len);
      const L = 8 * 131;
      assert.equal(hashOf(Blake3, { length: L }, message), c.hash, `hash, ${c.input_len} bytes`);
      assert.equal(hashOf(Blake3, { length: L, key }, message), c.keyed_hash, `keyed, ${c.input_len} bytes`);
      assert.equal(hashOf(Blake3, { length: L, context }, message), c.derive_key, `derive, ${c.input_len} bytes`);
    }
  });

  it('the same vectors fed in random pieces', () => {
    for (const c of B3.cases) {
      const message = input(c.input_len);
      const options = [{}, { key }, { context }].map((o) => ({ length: 8 * 131, ...o }));
      const want = [c.hash, c.keyed_hash, c.derive_key];
      options.forEach((o, i) => {
        const h = new Blake3(o);
        feed(h, message, c.input_len + i, 777);
        assert.equal(toHex(h.finalize()), want[i], `mode ${i}, ${c.input_len} bytes`);
      });
    }
  });

  it('the default is the first 256 bits of the extendable output; any shorter length is a prefix', () => {
    const c = B3.cases[B3.cases.length - 1];
    const message = input(c.input_len);
    assert.equal(hashOf(Blake3, {}, message), c.hash.slice(0, 64));
    for (const bytesOut of [1, 2, 31, 33, 63, 64, 65, 100, 131]) {
      assert.equal(hashOf(Blake3, { length: 8 * bytesOut }, message), c.hash.slice(0, 2 * bytesOut), `${bytesOut} bytes`);
    }
  });

  it('long output: consistent across the 62 KiB steps wasm produces it in, up to the 1 MiB limit', () => {
    const message = Buffer.from('extendable output');
    const long = hashOf(Blake3, { length: 8 * 100000 }, message);
    assert.equal(long.length, 200000);
    for (const n of [32, 63488, 63489, 70000, 100000]) {
      assert.equal(hashOf(Blake3, { length: 8 * n }, message), long.slice(0, 2 * n), `${n} bytes`);
    }
    assert.equal(hashOf(Blake3, { length: 8 * (1 << 20) }, message).length, 2 * (1 << 20));
  });

  it('a context longer than one chunk', () => {
    // No independent reference for this exact input; the Zig test checks long contexts against
    // std.crypto, and the other engine must agree.
    const long = bytes(3000, 21).toString('latin1');
    const here = hashOf(Blake3, { context: long }, 'material');
    const other = withJs(() => hashOf(Blake3, { context: long }, 'material'));
    assert.equal(here, other);
    assert.notEqual(here, hashOf(Blake3, { context: long.slice(0, 2999) }, 'material'));
  });
});

describe('the wasm and the JS engine agree, state included', () => {
  /** getState() JSON after every update, then the digest, for one scenario. */
  function trace(C, options, message, seed) {
    const h = new C(options);
    const states = [];
    let pos = 0;
    let x = seed;
    while (pos < message.length) {
      x = (Math.imul(x, 1664525) + 1013904223) >>> 0;
      const n = 1 + ((x >>> 8) % 3000);
      h.update(message.subarray(pos, pos + n));
      pos += n;
      states.push(JSON.stringify(h.getState()));
    }
    const digest = toHex(h.finalize());
    states.push(JSON.stringify(h.getState()));
    return { states, digest };
  }

  const cases = [
    [Blake2b, {}], [Blake2b, { length: 160, key: 'k', salt: 's', personalization: 'p' }],
    [Blake2s, {}], [Blake2s, { length: 96, key: bytes(32, 1) }],
    [Blake3, {}], [Blake3, { length: 1000 }], [Blake3, { key: bytes(32, 2) }], [Blake3, { context: 'agreement test' }],
  ];
  for (const [C, options] of cases) {
    it(`${C.name} ${JSON.stringify(options).slice(0, 60)}`, () => {
      for (const n of [0, 1, 63, 64, 65, 127, 128, 129, 1023, 1024, 1025, 4097, 70000, 140000]) {
        const message = bytes(n, n + 1);
        const wasm = trace(C, options, message, n);
        const js = withJs(() => trace(C, options, message, n));
        assert.deepEqual(wasm, js, `${n} bytes`);
      }
    });
  }
});

perEngine('state and reuse', () => {
  const cases = [
    ['blake2b', Blake2b, {}], ['blake2b', Blake2b, { length: 256, key: 'secret', salt: 'salt', personalization: 'person' }],
    ['blake2s', Blake2s, {}], ['blake2s', Blake2s, { length: 128, key: 'secret' }],
    ['blake3', Blake3, {}], ['blake3', Blake3, { length: 512, key: bytes(32, 4) }], ['blake3', Blake3, { context: 'ctx' }],
  ];
  for (const [name, C, options] of cases) {
    const label = `${name} ${JSON.stringify(options).slice(0, 50)}`;

    it(`${label}: getState() is JSON and setState() resumes at any offset`, () => {
      const message = bytes(5000, 9);
      const want = hashOf(C, options, message);
      for (const cut of [0, 1, 63, 64, 65, 127, 128, 129, 1023, 1024, 1025, 2048, 2049, 4999, 5000]) {
        const a = new C(options);
        a.update(message.subarray(0, cut));
        const state = JSON.parse(JSON.stringify(a.getState()));
        const b = new C(options);
        b.setState(state);
        b.update(message.subarray(cut));
        assert.equal(toHex(b.finalize()), want, `cut at ${cut}`);
      }
    });

    it(`${label}: finalize() does not change the state; update() continues; reset() starts over`, () => {
      const h = new C(options);
      h.update('hello ');
      const state = JSON.stringify(h.getState());
      const first = toHex(h.finalize());
      assert.equal(JSON.stringify(h.getState()), state);
      assert.equal(toHex(h.finalize()), first);
      assert.equal(first, hashOf(C, options, 'hello '));
      h.update('world');
      assert.equal(toHex(h.finalize()), hashOf(C, options, 'hello world'));
      h.reset();
      assert.equal(JSON.stringify(h.getState()), JSON.stringify(new C(options).getState()));
      h.update('hello world');
      assert.equal(toHex(h.finalize()), hashOf(C, options, 'hello world'));
    });

    it(`${label}: accepts bytes, and rejects strings with characters above 0xFF`, () => {
      const text = 'binary \x00\xff data';
      const bytesIn = Buffer.from(text, 'latin1');
      const want = hashOf(C, options, text);
      assert.equal(hashOf(C, options, new Uint8Array(bytesIn)), want);
      assert.equal(hashOf(C, options, bytesIn.buffer.slice(bytesIn.byteOffset, bytesIn.byteOffset + bytesIn.length)), want);
      assert.equal(hashOf(C, options, new DataView(bytesIn.buffer, bytesIn.byteOffset, bytesIn.length)), want);
      assert.throws(() => new C(options).update('Ā'), TypeError);
      assert.throws(() => new C(options).update(5), TypeError);
      assert.throws(() => new C(options).update(null), TypeError);
    });

    it(`${label}: is a Hasher, and its options are not changed`, () => {
      const given = { ...options };
      const h = new C(given);
      assert.ok(h instanceof Hasher);
      assert.deepEqual(given, options);
      assert.equal(C.length, 1);
    });
  }

  it('the pristine state', () => {
    assert.equal(JSON.stringify(new Blake3().getState()), '{"message":"","length":0,"chunks":0,"stack":[]}');
    assert.deepEqual(Object.keys(new Blake2b().getState()), ['message', 'length', 'counter', 'hash']);
    assert.equal(new Blake2b().getState().hash.length, 16);
    assert.equal(new Blake2s().getState().hash.length, 8);
    // A keyed hash starts with the zero-padded key block in the buffer.
    const keyed = new Blake2s({ key: 'ab' }).getState();
    assert.equal(keyed.message, 'ab' + '\x00'.repeat(62));
    assert.equal(keyed.length, 0);
  });

  it('BLAKE3 keeps the last chunk until finalize()', () => {
    const h = new Blake3();
    h.update(Buffer.alloc(1024));
    assert.equal(h.getState().chunks, 0);
    assert.equal(h.getState().message.length, 1024);
    h.update('x');
    assert.equal(h.getState().chunks, 1);
    assert.equal(h.getState().message.length, 1);
    assert.equal(h.getState().stack.length, 8);
    h.update(Buffer.alloc(2 * 1024));
    assert.equal(h.getState().chunks, 3);
    assert.equal(h.getState().stack.length, 16); // popcount(3) subtrees
  });

  it('BLAKE2 keeps the last block until finalize()', () => {
    const h = new Blake2b();
    h.update(Buffer.alloc(128));
    assert.equal(h.getState().counter, 0);
    h.update('x');
    assert.equal(h.getState().counter, 128);
    assert.equal(h.getState().message, 'x');
    assert.equal(h.getState().length, 129);
  });
});

describe('options', () => {
  it('lengths are bits, a multiple of 8, up to the size of the algorithm', () => {
    for (const [name, { C, digest }] of Object.entries(ALGOS)) {
      for (const length of [8, 16, 128, 8 * digest]) {
        assert.equal(new C({ length }).finalize().length, length / 8, `${name} ${length}`);
      }
      for (const bad of [0, 4, 12, 8 * digest + 8, -8, 1.5]) {
        assert.throws(() => new C({ length: bad }), RangeError, `${name} ${bad}`);
      }
      for (const bad of ['256', true, null, {}, NaN]) {
        assert.throws(() => new C({ length: bad }), (e) => e instanceof TypeError || e instanceof RangeError, `${name} ${String(bad)}`);
      }
      assert.equal(new C({ length: undefined }).options.length, 8 * digest);
    }
    assert.equal(new Blake3({ length: 8 }).finalize().length, 1);
    assert.equal(new Blake3({ length: 8 * (1 << 20) }).options.length, 8 * (1 << 20));
    for (const bad of [0, 7, 8 * (1 << 20) + 8, -8, 1.5]) assert.throws(() => new Blake3({ length: bad }), RangeError, String(bad));
  });

  it('BLAKE2 key, salt and personalization: limits, types, and the empty value', () => {
    for (const [name, { C, digest }] of Object.entries(ALGOS)) {
      const param = digest / 4;
      new C({ key: 'k'.repeat(digest) });
      assert.throws(() => new C({ key: 'k'.repeat(digest + 1) }), RangeError, `${name} key`);
      new C({ salt: 's'.repeat(param) });
      assert.throws(() => new C({ salt: 's'.repeat(param + 1) }), RangeError, `${name} salt`);
      new C({ personalization: 'p'.repeat(param) });
      assert.throws(() => new C({ personalization: 'p'.repeat(param + 1) }), RangeError, `${name} personalization`);
      for (const field of ['key', 'salt', 'personalization']) {
        assert.throws(() => new C({ [field]: 5 }), TypeError, `${name} ${field}`);
        assert.throws(() => new C({ [field]: null }), TypeError, `${name} ${field}`);
        assert.throws(() => new C({ [field]: 'Ā' }), TypeError, `${name} ${field}`);
      }
      // An empty key is no key; an empty salt or personalization is all zeros, which is the default.
      const plain = hashOf(C, {}, 'abc');
      assert.equal(hashOf(C, { key: '' }, 'abc'), plain);
      assert.equal(hashOf(C, { salt: '' }, 'abc'), plain);
      assert.equal(hashOf(C, { personalization: '' }, 'abc'), plain);
      // They change the digest, and a short salt is zero padded.
      assert.notEqual(hashOf(C, { key: 'k' }, 'abc'), plain);
      assert.notEqual(hashOf(C, { salt: 's' }, 'abc'), plain);
      assert.notEqual(hashOf(C, { personalization: 'p' }, 'abc'), plain);
      assert.equal(hashOf(C, { salt: 's' }, 'abc'), hashOf(C, { salt: 's\x00\x00' }, 'abc'));
      // Unknown options are ignored.
      assert.equal(hashOf(C, { rounds: 3 }, 'abc'), plain);
    }
    assert.throws(() => new Blake2b(5), TypeError);
    assert.equal(hashOf(Blake2b, null, 'abc'), hashOf(Blake2b, {}, 'abc'));
    assert.equal(hashOf(Blake2b, undefined, 'abc'), hashOf(Blake2b, {}, 'abc'));
  });

  it('BLAKE3 key and context', () => {
    assert.throws(() => new Blake3({ key: 'short' }), RangeError);
    assert.throws(() => new Blake3({ key: 'k'.repeat(33) }), RangeError);
    assert.throws(() => new Blake3({ key: 5 }), TypeError);
    assert.throws(() => new Blake3({ context: 5 }), TypeError);
    assert.throws(() => new Blake3({ context: 'Ā' }), TypeError);
    assert.throws(() => new Blake3({ key: 'k'.repeat(32), context: 'c' }), TypeError);
    assert.throws(() => new Blake3(5), TypeError);
    // The three modes differ, and the key can be bytes or a binary string.
    const key = bytes(32, 8);
    const modes = [hashOf(Blake3, {}, 'abc'), hashOf(Blake3, { key }, 'abc'), hashOf(Blake3, { context: 'abc' }, 'abc'), hashOf(Blake3, { context: '' }, 'abc')];
    assert.equal(new Set(modes).size, 4);
    assert.equal(hashOf(Blake3, { key: key.toString('latin1') }, 'abc'), modes[1]);
    assert.equal(hashOf(Blake3, { key: new Uint8Array(key) }, 'abc'), modes[1]);
    assert.equal(hashOf(Blake3, { context: new Uint8Array(Buffer.from('abc')) }, 'abc'), modes[2]);
  });

  it('options come back as a normalized copy', () => {
    const h = new Blake2b({ key: new Uint8Array([97, 98]), salt: 's' });
    assert.deepEqual(h.options, { length: 512, key: 'ab', salt: 's' });
    assert.deepEqual(new Blake3().options, { length: 256 });
    assert.deepEqual(new Blake3({ context: 'c' }).options, { length: 256, context: 'c' });
  });
});

perEngine('HMAC and the registry', () => {
  it('Hmac works over a keyed or unkeyed BLAKE hasher and never changes it', () => {
    for (const C of [Blake2b, Blake2s, Blake3]) {
      const hasher = new C();
      const before = JSON.stringify(hasher.getState());
      const mac = new Hmac('key', hasher);
      mac.update('message');
      const first = toHex(mac.finalize());
      assert.equal(toHex(mac.finalize()), first);
      assert.equal(JSON.stringify(hasher.getState()), before);
      mac.reset();
      mac.update('message');
      assert.equal(toHex(mac.finalize()), first);
      assert.equal(first.length, 64 * (C === Blake2b ? 2 : 1));
    }
  });

  it('HMAC-BLAKE3 is the RFC 2104 construction over BLAKE3', () => {
    const key = bytes(100, 3);
    const message = bytes(300, 4);
    const hashB3 = (m) => {
      const h = new Blake3();
      h.update(m);
      return Buffer.from(h.finalize(), 'latin1');
    };
    // block size 64: a key longer than the block is hashed first
    const k0 = Buffer.alloc(64);
    hashB3(key).copy(k0);
    const ipad = Buffer.from(k0).map((b) => b ^ 0x36);
    const opad = Buffer.from(k0).map((b) => b ^ 0x5c);
    const want = hashB3(Buffer.concat([opad, hashB3(Buffer.concat([ipad, message]))])).toString('hex');
    const mac = new Hmac(key, new Blake3());
    mac.update(message);
    assert.equal(toHex(mac.finalize()), want);
  });

  it('getHasher() and hash() know every name', () => {
    const expected = {
      'blake2b': [Blake2b, 512], 'blake2b-512': [Blake2b, 512], 'blake2b-384': [Blake2b, 384], 'blake2b-256': [Blake2b, 256],
      'blake2b-160': [Blake2b, 160], 'blake2b-128': [Blake2b, 128],
      'blake2s': [Blake2s, 256], 'blake2s-256': [Blake2s, 256], 'blake2s-224': [Blake2s, 224], 'blake2s-160': [Blake2s, 160],
      'blake2s-128': [Blake2s, 128],
      'blake3': [Blake3, 256],
    };
    for (const [name, [C, bits]] of Object.entries(expected)) {
      const hasher = CryptoApi.getHasher(name);
      assert.ok(hasher instanceof C, name);
      assert.equal(hasher.options.length, bits, name);
      assert.equal(CryptoApi.hash(name, 'abc').length, bits / 4, name);
      // An option overrides the length the name implies; the others are passed on.
      assert.equal(CryptoApi.hash(name, 'abc', { length: 64 }).length, 16, name);
    }
    for (const name of ['BLAKE2b', 'blake', 'blake2', 'blake2b-100', 'blake2s-512', 'blake3-256', 'blake-256']) {
      assert.equal(CryptoApi.getHasher(name), undefined, name);
    }
    assert.equal(CryptoApi.hash('blake2b-256', 'abc'), 'bddd813c634239723171ef3fee98579b94964e3bb1cb3e427262c8c068d52319');
    assert.equal(CryptoApi.hash('blake2s-128', 'abc'), 'aa4938119b1dc7b87cbad0ffd200d0ae');
    assert.equal(CryptoApi.hash('blake2b-160', ''), '3345524abf6bbe1809449224b5972c41790b6cf2');
    assert.equal(CryptoApi.hash('blake2b', 'abc', { key: 'key' }),
      '5c6a9a4ae911c02fb7e71a991eb9aea371ae993d4842d206e6020d46f5e41358c6d5c277c110ef86c959ed63e6ecaaaceaaff38019a43264ae06acf73b9550b1');
    assert.equal(CryptoApi.hash('blake2s', 'abc', { key: 'key', salt: 'salt', personalization: 'pers' }),
      '1a949e885f2c1ef0ed517cc62317f5f9ed7a67e8419b3f1b071daa9e1c2ae1f3');
  });

  it('CryptoApi.hash() encodes a string message as UTF-8, and takes bytes as they are', () => {
    const text = 'héllo 世界';
    for (const name of ['blake2b', 'blake2s', 'blake3']) {
      const want = hashOf(CryptoApi.getHasher(name).constructor, { length: CryptoApi.getHasher(name).options.length }, fromUtf(text));
      assert.equal(CryptoApi.hash(name, text), want, name);
      assert.equal(CryptoApi.hash(name, new Uint8Array(Buffer.from(text))), want, name);
    }
    assert.equal(CryptoApi.hmac('key', 'message', CryptoApi.getHasher('blake2s')),
      toHex(withMac(Blake2s, 'key', 'message')));
  });
});

function withMac(C, key, message) {
  const mac = new Hmac(key, new C());
  mac.update(message);
  return mac.finalize();
}
